import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"How Rimlink works","description":"","frontmatter":{"pageId":"overview","contentRevision":2},"headers":[],"relativePath":"en/overview.md","filePath":"en/overview.md"}'),n={name:"en/overview.md"};function r(i,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="how-rimlink-works" tabindex="-1">How Rimlink works <a class="header-anchor" href="#how-rimlink-works" aria-label="Permalink to &quot;How Rimlink works&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Process diagram"><li><strong>Home map</strong><span>A player simulates and saves their colony.</span></li><li><strong>Shared server</strong><span>World, permissions, wallets and escrow.</span></li><li><strong>Live host</strong><span>Sole map executor and save writer.</span></li><li><strong>Guest mirror</strong><span>Orders for owned/assigned pawns, not a second save.</span></li></ol><p>The server stores the shared world, settlement metadata, saves and transactions. Players develop their own colonies at their own pace; other settlements appear on the planet with presence indicators. Saves are uploaded and restored on the next login.</p><p>Chat, gifts, markets, auctions and procurement connect colonies without a shared simulation. Visits and asynchronous raids use a map copy. Live mode sends the host&#39;s active state to a guest; persistent coop additionally stores permissions for specific pawns.</p><h2 id="ownership" tabindex="-1">Who simulates the world and owns the save? <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Who simulates the world and owns the save? {#ownership}&quot;">​</a></h2><p>“Persistent” describes the server world and state between logins, not background simulation of every map. The server stores the planet, accounts, settlements, economy, queued events and accepted colony versions. The owner&#39;s running game simulates the home map. Offline colonists do not mine or advance through game days.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Simulation authority</th><th>Saved result</th></tr></thead><tbody><tr><td>Home colony</td><td>Your client</td><td>Home save accepted by the server</td></tr><tr><td>Ordinary visit</td><td>Local copy of a foreign map</td><td>The copy never replaces your home save</td></tr><tr><td>Asynchronous raid</td><td>Defender&#39;s game when they play</td><td>Raid outcome and permitted returns</td></tr><tr><td>Live / coop</td><td>Host&#39;s game</td><td>Only the host writes the canonical save</td></tr></tbody></table><p>Independent colonies can run at different speeds. Server deadlines, such as offer expiry, are not map ticks. An offline seller can be paid on the server without their colony advancing a week.</p><h2 id="boundaries" tabindex="-1">Which interactions are actually shared? <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Which interactions are actually shared? {#boundaries}&quot;">​</a></h2><p>Chat and social relationships connect players; goods and silver move through server escrow and mail. A raid or paid event can wait for its target&#39;s next login. Live enables simultaneous interaction; persistent coop adds saved permissions for host-owned pawns.</p><p>Choose a mode by purpose: an independent colony, a tour, combat, or control of the host&#39;s colonists? Friendship grants no colony control; alliance membership does not replace coop consent; influence colors do not lock territory. These systems share some rules, not permission ownership.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Offline colonies are not continuously simulated. Live does not make the guest the save owner. Alliances and influence do not grant control of another colony.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./players/live">Live: the active map</a></li><li><a href="./players/coop">Persistent shared colony</a></li><li><a href="./players/economy">Wallet, mail and market</a></li></ul>',17)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
